EventHandler.on(document, EVENT_CLICK_DATA_API, SELECTOR_DATA_TOGGLE, function (event) {
  // Only handle if not an input (inputs use focus)
  // Skip inline datepickers (they're always visible)
  if (this.tagName === 'INPUT' || this.dataset.bsInline === 'true') {
    return
  }

  event.preventDefault()
  Datepicker.getOrCreateInstance(this).toggle()
})

edits.after:
EventHandler.on(document, EVENT_CLICK_DATA_API, SELECTOR_DATA_TOGGLE, function (event) {
  // Skip inline datepickers (they're always visible)
  if (this.dataset.bsInline === 'true') {
    return
  }

  const instance = Datepicker.getOrCreateInstance(this)
  if (this.tagName === 'INPUT') {
    // For inputs, click should show the calendar (focusin also handles this,
    // but click may not trigger focus in all environments)
    event.preventDefault()
    instance.show()
  } else {
    event.preventDefault()
    instance.toggle()
  }
})
